// BEFORE - stateful, CANNOT be correctly horizontally scaled
const sessions = new Map(); // lives in THIS specific server
                              // instance's own memory only

app.post('/login', (req, res) => {
  const sessionId = generateSessionId();
  sessions.set(sessionId, { userId: req.body.userId, loggedInAt: new Date() });
  res.cookie('sessionId', sessionId);
  res.json({ success: true });
});

app.get('/profile', (req, res) => {
  const session = sessions.get(req.cookies.sessionId);
  // If a load balancer routes THIS request to a DIFFERENT server
  // instance than the one that handled /login, 'sessions' here is a
  // COMPLETELY DIFFERENT, EMPTY Map - the session is genuinely,
  // silently lost, even though the user just logged in successfully
  if (!session) return res.status(401).json({ success: false });
  res.json({ success: true, data: session });
});

// AFTER - stateless application servers, session state moved to a
// SHARED resource every instance equally, genuinely accesses
import { createClient } from 'redis';
const redisClient = createClient({ url: process.env.REDIS_URL });

app.post('/login', async (req, res) => {
  const sessionId = generateSessionId();
  await redisClient.set(`session:${sessionId}`, JSON.stringify({ userId: req.body.userId, loggedInAt: new Date() }), { EX: 86400 });
  res.cookie('sessionId', sessionId);
  res.json({ success: true });
});

app.get('/profile', async (req, res) => {
  const sessionData = await redisClient.get(`session:${req.cookies.sessionId}`);
  // ANY server instance can genuinely retrieve this SAME session data
  // from Redis, regardless of which specific instance originally
  // handled the /login request - the application itself is now
  // genuinely stateless, and horizontal scaling now works correctly
  if (!sessionData) return res.status(401).json({ success: false });
  res.json({ success: true, data: JSON.parse(sessionData) });
});

