function rateLimitMiddleware(req, res, next) {
  const key = req.ip;
  const count = requestCounts.get(key) || 0;
  if (count >= 100) {
    return res.status(429).json({ error: 'Too many requests' });
  }
  requestCounts.set(key, count + 1);
  next();
