// TODO: convert this to a Redis-backed, genuinely stateless
// implementation, with a 60-second expiration per IP's count

codingChallenge.solutionExample:
import { createClient } from 'redis';
const redisClient = createClient({ url: process.env.REDIS_URL });

async function rateLimitMiddleware(req, res, next) {
  const key = `ratelimit:${req.ip}`;
  const count = await redisClient.incr(key);

  if (count === 1) {
    await redisClient.expire(key, 60); // set expiration only on the
      // FIRST request in this window, establishing the 60-second period
  }

  if (count > 100) {
    return res.status(429).json({ error: 'Too many requests' });
  }

  next();
}

