interface Instance {
  url: string;
  activeConnections: number;
  healthy: boolean;
}

const instances: Instance[] = [
  { url: 'http://instance-1:3000', activeConnections: 0, healthy: true },
  { url: 'http://instance-2:3000', activeConnections: 0, healthy: true },
  { url: 'http://instance-3:3000', activeConnections: 0, healthy: true }
];

function selectInstance(): Instance | null {
  const healthyInstances = instances.filter((i) => i.healthy);
  if (healthyInstances.length === 0) return null; // every single
    // instance is currently unhealthy - a genuine, total outage

  // LEAST CONNECTIONS - pick whichever healthy instance currently
  // has the fewest active, in-progress requests
  return healthyInstances.reduce((least, current) =>
    current.activeConnections < least.activeConnections ? current : least
  );
}

async function routeRequest(req: Request): Promise<Response> {
  const instance = selectInstance();
  if (!instance) throw new Error('No healthy instances available');

  instance.activeConnections++;
  try {
    return await fetch(`${instance.url}${req.url}`, { method: req.method, headers: req.headers });
  } finally {
    instance.activeConnections--; // decrement regardless of
      // success or failure, keeping the count genuinely accurate
  }
}

// Continuous, independent health checking - directly extending
// Module 25 lesson 4's health-check endpoint pattern
async function checkInstanceHealth(instance: Instance) {
  try {
    const response = await fetch(`${instance.url}/health`, { signal: AbortSignal.timeout(2000) });
    instance.healthy = response.ok;
  } catch (err) {
    instance.healthy = false; // a timeout or connection failure
      // means this instance is genuinely, currently unreachable
  }
}

setInterval(() => instances.forEach(checkInstanceHealth), 5000); // every
  // 5 seconds, independently, continuously re-verify each instance's
  // genuine, current health

