interface Instance {
  url: string;
  healthy: boolean;
}

const instances: Instance[] = [
  { url: 'http://instance-1:3000', healthy: true },
  { url: 'http://instance-2:3000', healthy: true },
  { url: 'http://instance-3:3000', healthy: true }
];

let roundRobinIndex = 0;

function selectInstance(): Instance | null {
  const healthyInstances = instances.filter((i) => i.healthy);
  if (healthyInstances.length === 0) return null;

  const instance = healthyInstances[roundRobinIndex % healthyInstances.length];
  roundRobinIndex++;
  return instance;
}

async function checkInstanceHealth(instance: Instance) {
  try {
    const response = await fetch(`${instance.url}/health`, { signal: AbortSignal.timeout(2000) });
    instance.healthy = response.ok;
  } catch (err) {
    instance.healthy = false;
  }
}

setInterval(() => instances.forEach(checkInstanceHealth), 5000);

