// SCENARIO: A product page is reported as 'slow'. Before adding ANY
// caching layer, diagnose where the genuine delay actually occurs.

// STEP 1 - check the actual network waterfall (Module 4's habit,
// now applied at this larger scale): the HTML, CSS, and JS load
// quickly (180ms total) - STATIC ASSETS ARE NOT THE BOTTLENECK,
// ruling out layer 1 (CDN) as the relevant fix here

// STEP 2 - check the actual API response time for the product data
// itself: 2,400ms - THIS IS THE GENUINE BOTTLENECK

// STEP 3 - investigate WHY this specific API call is slow (directly
// extending Module 24 lesson 3's N+1/EXPLAIN diagnostic discipline):
// the endpoint runs a genuinely expensive aggregation query,
// recalculating a product's average rating from thousands of
// individual reviews on EVERY single request, even though the
// average rating itself only changes when a new review is submitted

// CONCLUSION: this is layer 3's territory specifically (application-
// level caching), NOT layer 1 (CDN, since static assets were never
// the problem) or layer 2 (reverse proxy, since this data is
// genuinely user-independent and could be cached, but the REAL fix
// is addressing the redundant recalculation specifically)

// THE FIX - Module 24's exact application-level caching pattern,
// correctly applied at the layer the evidence actually identified:
async function getProductWithRating(productId: string) {
  const cacheKey = `product-rating:${productId}`;
  const cached = await redisClient.get(cacheKey);
  if (cached) return JSON.parse(cached);

  const avgRating = await calculateExpensiveAverageRating(productId);
  await redisClient.set(cacheKey, JSON.stringify(avgRating), { EX: 3600 });
  return avgRating;
}
// Invalidated explicitly (Module 24 lesson 4's exact pattern) the
// moment a new review is genuinely submitted, not left to expire blindly

